// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.intentimport kotlin.reflect.KClass/** * NOUS — Intent hierarchy. * * Result of Layer 0 (IntentClassifier). Each Intent type carries its slots * (extracted entities). [Intent.Unknown] means classification failed — * Layer 0 defers to Layer 1+ with hint. * * @see <a href="docs/spec/module2-spec-review.pdf">§4 Layer 0</a> */sealed interface Intent {    // ─── System controls ──────────────────────────────────────────────────    data object TorchOn : Intent    data object TorchOff : Intent    data class VolumeUp(val amount: Int? = null) : Intent    data class VolumeDown(val amount: Int? = null) : Intent    data class SetVolume(val level: Int, val stream: String = "media") : Intent    data class SetBrightness(val level: Int) : Intent  // 0-100    /** Increase brightness by one step (strategy §2: 9 built-in rules). */    data class BrightnessUp(val amount: Int? = null) : Intent    /** Decrease brightness by one step. */    data class BrightnessDown(val amount: Int? = null) : Intent    data object Mute : Intent    data object Unmute : Intent    data class SetRingerMode(val mode: String) : Intent  // normal/vibrate/silent    /** Turn the screen on. */    data object ScreenOn : Intent    /** Turn the screen off (lock). */    data object ScreenOff : Intent    /** Toggle Do Not Disturb mode. */    data object ToggleDnd : Intent    /** Toggle battery saver mode. */    data object ToggleBatterySaver : Intent    // ─── Communications ───────────────────────────────────────────────────    data class Call(val contact: String? = null) : Intent    data class SendSms(val contact: String? = null, val message: String? = null) : Intent    data class SendEmail(        val to: String? = null,        val subject: String? = null,        val body: String? = null,    ) : Intent    // ─── Apps ─────────────────────────────────────────────────────────────    data class OpenApp(val packageName: String? = null, val appName: String? = null) : Intent    data class SearchWeb(val query: String? = null) : Intent    // ─── Knowledge (LLM territory) ────────────────────────────────────────    data class Question(val topic: String? = null, val raw: String) : Intent    data class Explain(val topic: String? = null, val raw: String) : Intent    data class Summarize(val target: String? = null, val raw: String) : Intent    data class Translate(val text: String? = null, val targetLanguage: String? = null) : Intent    // ─── Productivity ─────────────────────────────────────────────────────    data class SetAlarm(val time: String? = null, val label: String? = null) : Intent    data class SetTimer(val duration: String? = null, val label: String? = null) : Intent    data class SetReminder(val text: String? = null, val time: String? = null) : Intent    data class CreateNote(val text: String? = null) : Intent    data class CreateCalendarEvent(        val title: String? = null,        val time: String? = null,        val location: String? = null,    ) : Intent    // ─── Persona (Module 15) ──────────────────────────────────────────────    /** Switch the active persona. [personaId] is the persona's ID (e.g., "atlas"). */    data class SwitchPersona(val personaId: String? = null, val personaName: String? = null) : Intent    /** List available personas (for UI / "what personas are available?"). */    data object ListPersonas : Intent    // ─── Automation ───────────────────────────────────────────────────────    data class CreateAutomation(val trigger: String? = null, val action: String? = null) : Intent    data object ListAutomations : Intent    data class EnableAutomation(val id: String? = null) : Intent    data class DisableAutomation(val id: String? = null) : Intent    // ─── Agentic ──────────────────────────────────────────────────────────    /** Multi-step task — needs Layer 5 (Agentic). */    data class MultiStep(val description: String, val raw: String) : Intent    // ─── Compound (multi-intent) — Fixes #23 ──────────────────────────────    /**     * Multiple intents in one utterance.     *     * Example: "torch on and call mom" → Compound(     *   intents = [TorchOn, Call("mom")],     *   executor = SEQUENTIAL     * )     */    data class Compound(        val intents: List<Intent>,        val executor: CompoundExecutor,    ) : Intent    // ─── Unknown — defer to next layer ────────────────────────────────────    /**     * Classification failed. Layer 0 defers to Layer 1+.     *     * [hint] carries the best-guess intent (if any) for Layer 1 hint mechanism.     */    data class Unknown(val hint: KClass<out Intent>? = null, val raw: String) : Intent}/** * How a [Intent.Compound] should be executed. * * @see <a href="docs/spec/module2-spec-review.pdf">§4.5 CompoundIntent</a> */enum class CompoundExecutor {    /** Execute intents in sequence — "torch on and call mom" → torch first, then call. */    SEQUENTIAL,    /** Execute intents in parallel — "mute and dim screen" → both at once. */    PARALLEL,    /** First intent is condition; if true, execute rest — "if battery < 20% then saver". */    CONDITIONAL,}